#include <stdio.h>
#include <stdlib.h>

#define MAX_SIZE 500

typedef struct ListNode {
    int ele;
    struct ListNode *prev;
    struct ListNode *next;
} ListNode;

typedef struct {
    int size;
    ListNode *head;
    ListNode *tail;
} LinkedList;

LinkedList *new_LinkedList();

void addLast_LinkedList(LinkedList *link, int ele);

int m, n, k;
int matrix[MAX_SIZE][MAX_SIZE] = {0};
int visited[MAX_SIZE][MAX_SIZE] = {0};
int offsets[4][2] = {{-1, 0},
                     {1,  0},
                     {0,  -1},
                     {0,  1}};

int maxHeight;
int minStep;

int getResult();

void bfs();

int main() {
    scanf("%d %d %d", &m, &n, &k);

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            scanf("%d", &matrix[i][j]);
        }
    }

    // 到达matrix[0][0]高度的山峰，最短步数是0
    maxHeight = matrix[0][0];
    minStep = 0;

    // 广搜
    bfs();

    if (minStep == 0) {
        // 输出描述：如果没有可以爬的山峰，则高度和步数都返回0。
        puts("0 0");
    } else {
        printf("%d %d", maxHeight, minStep);
    }

    return 0;
}

void bfs() {
    // 广搜队列
    LinkedList *queue = new_LinkedList();

    // 首先是(0,0)位置进入队列，且被标记为访问过
    addLast_LinkedList(queue, 0 * n + 0);
    visited[0][0] = 1;

    // 此时消耗步数为0
    int step = 0;

    while (queue->size > 0) {
        // 这里没有用queue.removeFirst来控制广搜，而是使用newQueue来控制广搜，因为这样更方便操作step
        LinkedList *newQueue = new_LinkedList();
        step++;

        // 遍历同一层的所有节点
        ListNode *cur = queue->head;
        while (cur != NULL) {
            int x = cur->ele / n;
            int y = cur->ele % n;

            int lastHeight = matrix[x][y];

            // 四个方向位置
            for (int i = 0; i < 4; i++) {
                int newX = x + offsets[i][0];
                int newY = y + offsets[i][1];

                // 新位置越界则无法继续广搜
                if (newX < 0 || newX >= m || newY < 0 || newY >= n) continue;

                // 新位置已访问过，则无需重复广搜
                if (visited[newX][newY]) continue;

                // 前后位置高度差在k以内, 则可以进入新位置
                int curHeight = matrix[newX][newY];

                if (abs(curHeight - lastHeight) <= k) {
                    // 标记新位置已访问
                    visited[newX][newY] = 1;

                    // 如果此时到达新位置高度的步数step更小，则更新对应高度的最小步数
                    if (curHeight > maxHeight || (curHeight == maxHeight && step < minStep)) {
                        maxHeight = curHeight;
                        minStep = step;
                    }

                    // 新位置加入下一层广搜队列
                    addLast_LinkedList(newQueue, newX * n + newY);
                }
            }

            cur = cur->next;
        }

        queue = newQueue;
    }
}


LinkedList *new_LinkedList() {
    LinkedList *link = (LinkedList *) malloc(sizeof(LinkedList));

    link->size = 0;
    link->head = NULL;
    link->tail = NULL;

    return link;
}

void addLast_LinkedList(LinkedList *link, int ele) {
    ListNode *node = (ListNode *) malloc(sizeof(ListNode));

    node->ele = ele;
    node->prev = NULL;
    node->next = NULL;

    if (link->size == 0) {
        link->head = node;
        link->tail = node;
    } else {
        link->tail->next = node;
        node->prev = link->tail;
        link->tail = node;
    }

    link->size++;
}
